export default function Icon({ name, width, height, className }) {
  const icon = icons[name];
  if (!icon) return null;
  const [, , w, h] = icon.box.split(' ').map(Number);
  return (
    <svg
      className={className}
      viewBox={icon.box}
      width={width || w}
      height={height || (width ? (width * h) / w : h)}
      aria-hidden="true"
      focusable="false"
    >
      {icon.body}
    </svg>
  );
}
